script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let selectedTabIndex = event.payload.selectedTabIndex;
	let selectedTab = '';
	switch(selectedTabIndex){
		case 0: 
			selectedTab = 'Attributes';
			break;
		case 1: 
			selectedTab = 'Application Services';
			break;
		case 2: 
			selectedTab = 'Related Items';
			break;
		case 3: 
			selectedTab = 'Changes';
			break;
		default: 
			selectedTab = selectedTabIndex + '';
	}
	return {
		event: "Unified Map Contextual Module Clicked",
		value: {selection: selectedTab}
	};
}

